from lib import *
S = SS('w31')
steps = [
    step("SO_BROADCAST:往广播地址发 UDP 必须先打开这个套接字选项。不打开时,往受限广播 255.255.255.255 和往本网段的定向广播地址发,都被内核拒绝:[Errno 13] Permission denied;打开之后两者都发送成功(8 字节)。getsockopt(SO_BROADCAST) 默认是 0。对单播地址发包不需要这个选项。这个选项是一道保险:防止应用不小心把包发给全网。", t=tl(S(1)), mark=lidx(S(1), '未打开 → 失败'), done=lidx(S(1), '打开 → 发送成功', 'getsockopt(SO_BROADCAST)'), b=bars([['未打开 · 受限广播', 0, '失败 EACCES'], ['打开 · 受限广播', 8, '成功 8 字节'], ['未打开 · 定向广播', 0, '失败 EACCES'], ['打开 · 定向广播', 8, '成功 8 字节']], 8, mark=[0, 2], done=[1, 3]), kv=KV([['SO_BROADCAST 默认', '0:关'], ['未打开', 'Permission denied'], ['打开', '两种广播都能发']], ['未打开'])),
    step("两种广播地址在线上:受限广播 255.255.255.255 和本网段的定向广播地址(子网最后一个地址)。en0 上抓到的两个帧,以太网目的 MAC 都是 ff:ff:ff:ff:ff:ff,源地址是本机,TTL 64;受限广播的帧长 49 字节(IP 总长 35),定向广播 50 字节(IP 总长 36)。route get 这两个地址,接口都是 en0,标志都带 BROADCAST 和 IFSCOPE。两种广播在以太网上没有区别,同一网段的所有设备的网卡都会收下;区别在 IP 目的:受限广播永远不会被路由器转发,定向广播理论上可以被转发到目标子网(现在的路由器默认都不转发,这一点没有验证)。", t=tl(S(2)), mark=lidx(S(2), '受限广播),源地址', '定向广播地址,源地址'), done=lidx(S(2), 'route get 255', 'route get 定向', '两种广播的以太网目的地址'), kv=KV([['以太网目的 MAC', '两种都是 ff:ff:ff:ff:ff:ff'], ['受限广播', '255.255.255.255,不被路由器转发'], ['定向广播', '子网最后一个地址'], ['route get', '接口 en0,标志含 BROADCAST']], ['以太网目的 MAC'])),
    step("本机上谁能收到广播:5 个接收套接字(SO_REUSEPORT)分别绑定 0.0.0.0、本机 en0 地址、定向广播地址、127.0.0.1、255.255.255.255,发送方发一个定向广播和一个受限广播。发定向广播:绑 0.0.0.0 的收到,绑定向广播地址的收到,绑本机 en0 地址的和 127.0.0.1 的没收到;绑 255.255.255.255 直接失败(Can't assign requested address)。发受限广播:只有绑 0.0.0.0 的收到,连绑定向广播地址的也没收到。也就是说广播只交给绑定了通配地址(或恰好是那个广播地址)的套接字;绑在本机单播地址上的收不到——这是很多“收不到广播”的坑。", t=tl(S(3)), mark=lidx(S(3), '发 定向广播', '发 受限广播'), done=lidx(S(3), '也就是说广播只会'), b=bars([['定向广播 · 收到的接收方', 2, '2 / 4'], ['受限广播 · 收到的接收方', 1, '1 / 4']], 4, mark=[0, 1], done=[]), kv=KV([['绑 0.0.0.0', '两种广播都收到'], ['绑定向广播地址', '只收定向广播'], ['绑本机单播地址 / 127.0.0.1', '都收不到'], ['绑 255.255.255.255', '绑定失败']], ['绑本机单播地址 / 127.0.0.1'])),
    step("局域网上的广播流量有多少(en0,30 秒,别的设备的帧只统计个数):以太网目的 MAC 是 ff:ff:ff:ff:ff:ff 的帧共 828 个(373,406 字节,平均 27.6 帧/秒、99.6 Kbit/s):IPv4 UDP 529 个、ARP 271 个、其它(以太网类型字段不是 IPv4 / ARP / IPv6)28 个。UDP 广播的目的端口:5353 有 384 个、137(NetBIOS 名字服务)84 个、12476 有 22 个、5684 有 17 个、51007 有 9 个、138(NetBIOS 数据报)3 个、68(DHCP 客户端端口)3 个、161 有 2 个。5353 通常是 mDNS——它们的以太网目的 MAC 是广播,IP 目的地址是不是 mDNS 的组播地址这里没有统计。每个广播帧都会让同一网段里每一台设备的网卡和内核处理一遍,即使它们不关心;网段越大,代价越大。", t=tl(S(4)), mark=lidx(S(4), '30 秒共 828', 'IPv4 UDP 广播的目的端口'), done=lidx(S(4), '每个广播帧'), b=bars([['IPv4 UDP', 529, '529'], ['ARP', 271, '271'], ['其它', 28, '28']], 529, mark=[0], done=[1, 2]), kv=KV([['30 秒', '828 个广播帧 · 99.6 Kbit/s'], ['IPv4 UDP', '529 个(5353 占 384 个)'], ['ARP', '271 个'], ['NetBIOS 137 / 138', '84 / 3 个']], ['IPv4 UDP'])),
]
A = mkartw('w31', 31, '网络协议,UDP,广播,SO_BROADCAST,受限广播,定向广播,真实验证,动画演示',
    '往广播地址发 UDP 必须先开 SO_BROADCAST(否则 EACCES);受限广播与定向广播在以太网上都是 ff:ff:ff:ff:ff:ff;只有绑 0.0.0.0 的套接字能收到受限广播;局域网上 30 秒有 828 个广播帧、约 99.6 Kbit/s。',
    '广播地址有两种,SO_BROADCAST 这个选项为什么必须打开,本机的套接字绑在哪里才能收到广播?局域网上每秒到底有多少广播?这篇用本机和 en0 上的真实流量一一验证。',
    [('EACCES', '没有 SO_BROADCAST 时往广播地址发 UDP 的错误:Permission denied'), ('ff:ff:ff:ff:ff:ff', '受限广播与定向广播共同的以太网目的 MAC'), ('828 个 / 30 秒', '本机所在局域网上的广播帧数(约 99.6 Kbit/s),其中 ARP 271 个、IPv4 UDP 529 个')],
    [('发送', '<p>广播必须先打开 SO_BROADCAST,否则内核返回 Permission denied;单播不需要。</p>'),
     ('两种广播', '<p>255.255.255.255 是受限广播,不会离开本网段;子网最后一个地址是定向广播。两者在以太网上都是 ff:ff:ff:ff:ff:ff。</p>'),
     ('接收', '<p>只有绑定了通配地址 0.0.0.0(或恰好是那个广播地址)的套接字才能收到广播;绑在本机单播地址 / 127.0.0.1 上的收不到。</p>'),
     ('代价', '<p>局域网 30 秒有 828 个广播帧,每一台设备都要处理;这是下一篇组播要解决的问题。</p>')],
    steps,
    [ENV_W + '。前三节在本机 en0 / 回环上做(广播发到端口 33435 或随机端口,没有人监听);第四节被动抓 30 秒,别的设备的帧只统计个数,不写任何地址;抓到的“其它”类型是以太网类型字段不是 IPv4 / ARP / IPv6 的帧,没有进一步解析',
     '没有验证:定向广播是否会被路由器转发(假设现在默认都不转发);广播风暴(环路)的触发与抑制;Wi-Fi 接入点如何把组播变成广播发送(5353 的帧是广播 MAC,但没有统计它们的 IP 目的地址);IPv6 没有广播,用组播代替(见 NDP 一篇);IP_BOUND_IF 对多网卡机器上受限广播的影响'],
    'UDP 广播')
